INSERT INTO app_private.coaching_models (model_key,name_i18n,focus_i18n,limitation_i18n,source_title,source_url,source_kind,topic_tags) VALUES
  ('egyptian_goal_planning_v1','{"en":"Egyptian Goal Planning","ru":"Египетский коучинг","es":"Planificación egipcia"}'::jsonb,'{"en":"From personal desire to values, action, strengths and resources.","ru":"От живого желания — к ценностям, действию, уникальности и ресурсам.","es":"Del deseo personal a los valores, la acción y los recursos."}'::jsonb,'{"en":"An authored symbolic reflection using Egyptian imagery; not a verified historical, clinical or psychometric model.","ru":"Авторская символическая практика по египетским образам; не исторически валидированная психометрическая или лечебная методика.","es":"Práctica simbólica de autor; no es un modelo histórico, clínico o psicométrico validado."}'::jsonb,'ЕГИПЕТСКОЕ ПЛАНИРОВАНИЕ.pdf; Египетская Методичка.doc · Andrey Litvinov','https://github.com/andylitvinov-design/books/issues/1708','original',ARRAY['goal','growth','confidence','motivation','decision']::text[]),
  ('greek_goal_planning_v1','{"en":"Greek Goal Planning","ru":"Греческий коучинг","es":"Planificación griega"}'::jsonb,'{"en":"Connect desire, courage, order, meaning, ideal form and fullness of purpose.","ru":"Соединить желание, волю, порядок, смысл, идеальный образ и полноту цели.","es":"Conectar deseo, coraje, orden, sentido, ideal y propósito."}'::jsonb,'{"en":"An authored symbolic adaptation of ancient concepts; not a standardized psychometric method or academic consensus.","ru":"Авторская символическая интерпретация античных понятий, не стандартизированный тест и не академический консенсус.","es":"Interpretación simbólica de autor; no es un test estandarizado ni un consenso académico."}'::jsonb,'grecheskoe-planirovanie.docx; antichnaya-metafizika.docx · Andrey Litvinov','https://github.com/andylitvinov-design/books/issues/1708','original',ARRAY['goal','growth','career','decision','creativity']::text[])
