INSERT INTO app_private.coaching_steps (model_key,step_key,model_order,title_i18n,emphasis_i18n,key_question_i18n) VALUES
  ('egyptian_goal_planning_v1','ka',1,'{"en":"Ka · Desire","ru":"КА · Желание","es":"Ka · Deseo"}'::jsonb,'{"en":"Find your own desire","ru":"Найти своё живое желание","es":"Reconocer el deseo propio"}'::jsonb,'{"en":"What do I truly want?","ru":"Чего я действительно хочу?","es":"¿Qué deseo de verdad?"}'::jsonb),
  ('egyptian_goal_planning_v1','ba',2,'{"en":"Ba · Vision","ru":"БА · Образ и мысль","es":"Ba · Visión"}'::jsonb,'{"en":"Envision a concrete result","ru":"Представить конкретный результат","es":"Imaginar un resultado concreto"}'::jsonb,'{"en":"What result do I want to create?","ru":"Какой результат я хочу получить?","es":"¿Qué resultado quiero crear?"}'::jsonb),
  ('egyptian_goal_planning_v1','ib',3,'{"en":"Ib · Values","ru":"ИБ · Сердце и ценности","es":"Ib · Valores"}'::jsonb,'{"en":"Connect the goal with values","ru":"Соединить цель с ценностями","es":"Conectar el objetivo con los valores"}'::jsonb,'{"en":"Which value stands behind my goal?","ru":"Какая ценность стоит за моей целью?","es":"¿Qué valor hay detrás de mi objetivo?"}'::jsonb),
  ('egyptian_goal_planning_v1','sah',4,'{"en":"Sah · Contribution","ru":"САХ · Смысл и масштаб","es":"Sah · Contribución"}'::jsonb,'{"en":"Imagine the benefit and scale","ru":"Увидеть вклад и масштаб","es":"Imaginar el aporte y su alcance"}'::jsonb,'{"en":"What contribution do I want this goal to make?","ru":"Какой вклад я хочу внести этой целью?","es":"¿Qué contribución quiero hacer con este objetivo?"}'::jsonb),
  ('egyptian_goal_planning_v1','haibit',5,'{"en":"Khaibit · Experience and action","ru":"ХАЙБИТ · Опыт и действие","es":"Jaibit · Experiencia y acción"}'::jsonb,'{"en":"Use previous experience, then act","ru":"Опыт и первый реальный шаг","es":"Aprovechar la experiencia y actuar"}'::jsonb,'{"en":"Which past experience can help me?","ru":"Какой прошлый опыт поможет мне?","es":"¿Qué experiencia pasada puede ayudarme?"}'::jsonb),
  ('egyptian_goal_planning_v1','hu',6,'{"en":"Hu · Unique strength","ru":"ХУ · Уникальность","es":"Hu · Fortaleza única"}'::jsonb,'{"en":"Name a personal strength","ru":"Назвать личную сильную сторону","es":"Reconocer una fortaleza"}'::jsonb,'{"en":"Which strength makes my approach unique?","ru":"Какая моя особенность поможет реализовать цель?","es":"¿Qué fortaleza hace único mi enfoque?"}'::jsonb),
  ('egyptian_goal_planning_v1','ren',7,'{"en":"Ren · Becoming","ru":"РЕН · Имя и идентичность","es":"Ren · Identidad"}'::jsonb,'{"en":"Notice the person you are becoming","ru":"Увидеть желаемую идентичность","es":"Ver en quién te conviertes"}'::jsonb,'{"en":"Who am I becoming as I pursue this goal?","ru":"Каким человеком я становлюсь, достигая этой цели?","es":"¿En quién me convierto al perseguir este objetivo?"}'::jsonb),
  ('egyptian_goal_planning_v1','sekhem',8,'{"en":"Sekhem · Support","ru":"СЕКХЕМ · Ресурсы","es":"Sejem · Apoyo"}'::jsonb,'{"en":"Identify support and resources","ru":"Найти ресурсы и поддержку","es":"Identificar recursos y apoyos"}'::jsonb,'{"en":"What support do I need now?","ru":"Какая поддержка мне сейчас нужна?","es":"¿Qué apoyo necesito ahora?"}'::jsonb),
