  ('greek_goal_planning_v1','logos',3,'{"en":"Logos · Order","ru":"ЛОГОС · Порядок","es":"Logos · Orden"}'::jsonb,'{"en":"Organize your plan","ru":"Упорядочить действия","es":"Organizar el plan"}'::jsonb,'{"en":"What do I need to organize to move forward?","ru":"Что мне нужно упорядочить для движения к цели?","es":"¿Qué necesito organizar para avanzar?"}'::jsonb),
  ('greek_goal_planning_v1','nous',4,'{"en":"Nous · Meaning","ru":"НООС · Смысл","es":"Noûs · Sentido"}'::jsonb,'{"en":"Find the larger meaning","ru":"Найти больший смысл","es":"Encontrar un significado mayor"}'::jsonb,'{"en":"What larger meaning do I see in this goal?","ru":"Какой больший смысл я вижу в этой цели?","es":"¿Qué significado más profundo veo en esta meta?"}'::jsonb),
  ('greek_goal_planning_v1','eidos',5,'{"en":"Eidos · Ideal form","ru":"ЭЙДОС · Идеальная форма","es":"Eidos · Forma ideal"}'::jsonb,'{"en":"Visualize an ideal outcome","ru":"Увидеть эталон результата","es":"Visualizar el resultado ideal"}'::jsonb,'{"en":"What would the ideal outcome of my goal look like?","ru":"Как выглядит идеальный результат моей цели?","es":"¿Cómo sería el resultado ideal de mi objetivo?"}'::jsonb),
  ('greek_goal_planning_v1','idea',6,'{"en":"Idea · Guiding purpose","ru":"ИДЕЯ · Замысел","es":"Idea · Propósito"}'::jsonb,'{"en":"Name the central idea","ru":"Назвать главный замысел","es":"Nombrar la idea central"}'::jsonb,'{"en":"What central idea does my goal express?","ru":"Какую главную идею выражает моя цель?","es":"¿Qué idea central expresa mi objetivo?"}'::jsonb),
  ('greek_goal_planning_v1','daimon',7,'{"en":"Daimon · Identity","ru":"ГЕНИЙ / ДАЙМОН · Путь","es":"Daimon · Identidad"}'::jsonb,'{"en":"Reflect on who you become","ru":"Увидеть образ себя на пути","es":"Reflexionar en quién te conviertes"}'::jsonb,'{"en":"Who do I want to become on this journey?","ru":"Каким человеком я хочу стать на этом пути?","es":"¿En quién quiero convertirme en este camino?"}'::jsonb),
  ('greek_goal_planning_v1','telos',8,'{"en":"Telos · Full potential","ru":"ТЕЛОС · Полнота результата","es":"Telos · Plenitud"}'::jsonb,'{"en":"Imagine the goal at its fullest","ru":"Увидеть полный масштаб цели","es":"Imaginar el objetivo en plenitud"}'::jsonb,'{"en":"What could my goal become at its fullest?","ru":"Какого наибольшего раскрытия может достичь моя цель?","es":"¿Hasta dónde podría desarrollarse mi objetivo?"}'::jsonb)
